// Standalone reproduction for symphonia-bundle-mp3's layer3::hybrid_synthesis::antialias()
// clobbering `rzero` for mixed (long + short) blocks.
//
// The MPEG-1 Layer III bitstreams used here are generated by this program (a small bit writer -
// no encoder is installed on most machines that would emit mixed_block_flag = 1, LAME never does)
// and written out as real .mp3 files. They are then decoded through Symphonia's real public API -
// `symphonia::default::get_probe()` -> `MpaReader` -> `MpaDecoder` - i.e. exactly the path any
// caller decoding an .mp3 file goes through. The .mp3 file *is* the genuine external input; there
// is no second participant whose behaviour is being stood in for.
//
// Part 1 - self-contained differential, needs nothing installed.
//
//   Three streams are generated that are bit-identical except for the marked field:
//
//     A: mixed_block_flag = 1, spectral coefficients coded over 0..576
//     B: mixed_block_flag = 1, spectral coefficients coded over 0..36 (the 2 long sub-bands only)
//     C: mixed_block_flag = 0, spectral coefficients coded over 0..576   (control)
//
//   A's and B's first 36 coefficients are bit-identical, so a correct decoder must produce
//   clearly different PCM for A and B. If A and B decode to *identical* PCM, every coefficient
//   above sub-band 2 (1378 Hz at 44100 Hz) was discarded. C shows the very same coefficients do
//   survive when the block is not mixed.
//
// Part 2 - cross-check against ffmpeg, if ffmpeg is on PATH (skipped otherwise).
//
//   ffmpeg is the reference decoder symphonia-check itself uses for MP3. Symphonia is compared
//   against it for A/B/C, and then over a sweep of sample rates, block types and rzero positions.
//
// Exit code 1 (and a "BUG REPRODUCED" line) when A and B decode identically.

use std::io::Cursor;
use std::path::{Path, PathBuf};

use symphonia::core::audio::GenericAudioBufferRef;
use symphonia::core::codecs::CodecParameters;
use symphonia::core::codecs::audio::AudioDecoderOptions;
use symphonia::core::errors::Result;
use symphonia::core::formats::probe::Hint;
use symphonia::core::formats::{FormatOptions, TrackType};
use symphonia::core::io::MediaSourceStream;

/// MSB-first bit writer.
struct BitWriter {
    buf: Vec<u8>,
    cur: u8,
    n: u32,
}

impl BitWriter {
    fn new() -> Self {
        BitWriter { buf: Vec::new(), cur: 0, n: 0 }
    }

    fn write(&mut self, value: u32, bits: u32) {
        assert!(bits <= 32);
        for i in (0..bits).rev() {
            self.cur = (self.cur << 1) | (((value >> i) & 1) as u8);
            self.n += 1;
            if self.n == 8 {
                self.buf.push(self.cur);
                self.cur = 0;
                self.n = 0;
            }
        }
    }

    fn finish(mut self) -> Vec<u8> {
        if self.n > 0 {
            self.buf.push(self.cur << (8 - self.n));
        }
        self.buf
    }
}

/// 2^(0.25 * (180 - 210)) = 2^-7.5. Keeps the decoded samples well away from clipping, so the
/// symphonia/ffmpeg comparison is not distorted by either decoder's clamping.
const GLOBAL_GAIN: u32 = 180;

#[derive(Clone, Copy, PartialEq, Eq)]
enum Block {
    /// window_switching_flag = 0.
    Long,
    /// window_switching_flag = 1, block_type = 0b10.
    Short { mixed: bool },
}

#[derive(Clone, Copy)]
struct Cfg {
    /// 0 = 44100 Hz, 1 = 48000 Hz, 2 = 32000 Hz.
    sr_idx: u32,
    block: Block,
    /// Number of count1 quadruples, i.e. `4 * n_quads` spectral coefficients per granule.
    n_quads: usize,
}

impl Cfg {
    fn sample_rate(&self) -> u32 {
        [44100, 48000, 32000][self.sr_idx as usize]
    }

    /// MPEG-1 Layer III frame size at 320 kbps, no padding.
    fn frame_size(&self) -> usize {
        (144 * 320_000 / self.sample_rate()) as usize
    }
}

/// The count1 quadruples of one granule. Every quadruple covers 4 consecutive spectral
/// coefficients, and its value is a 4-bit mask of which of those coefficients is non-zero.
///
/// All quadruples are 0b1111 (four non-zero coefficients) except quadruples 7 and 8: coefficients
/// 28..36 are deliberately left at zero. That keeps this repro clear of a *separate* problem in
/// requantize() (mixed blocks requantize their long part over `SFB_MIXED_BANDS[..switch]`, which
/// stops at coefficient 30, so coefficients 30..36 of a mixed block are never scaled by
/// 2^(0.25*A)) - which would otherwise dominate the decoded amplitude and obscure this candidate.
fn quads(n_quads: usize) -> Vec<u32> {
    (0..n_quads).map(|q| if q == 7 || q == 8 { 0b0000 } else { 0b1111 }).collect()
}

/// Build one MPEG-1 Layer III frame (mono, 320 kbps, no CRC) whose two granules both carry
/// `4 * cfg.n_quads` spectral coefficients.
fn build_frame(cfg: Cfg) -> Vec<u8> {
    assert!(cfg.n_quads * 4 <= 576);

    let quads = quads(cfg.n_quads);

    // Quads table B codes every value in a fixed 4 bits, followed by one sign bit per non-zero
    // coefficient. part2 (the scale factors) is 0 bits long because scalefac_compress == 0, so
    // part2_3_length is exactly the length of the count1 partition.
    let part2_3_length: u32 = quads.iter().map(|v| 4 + v.count_ones()).sum();
    assert!(part2_3_length < 4096);

    let mut w = BitWriter::new();

    // ---- Frame header (32 bits) ----
    w.write(0x7ff, 11); // sync
    w.write(0b11, 2); // version: MPEG-1
    w.write(0b01, 2); // layer: III
    w.write(1, 1); // protection_bit: no CRC
    w.write(14, 4); // bitrate_index: 320 kbps
    w.write(cfg.sr_idx, 2); // sampling_frequency
    w.write(0, 1); // padding_bit
    w.write(0, 1); // private_bit
    w.write(0b11, 2); // mode: single channel
    w.write(0b00, 2); // mode_extension
    w.write(0, 1); // copyright
    w.write(0, 1); // original
    w.write(0b00, 2); // emphasis

    // ---- side_info (17 bytes = 136 bits for MPEG-1 mono) ----
    w.write(0, 9); // main_data_begin: main data starts in this frame
    w.write(0, 5); // private_bits
    w.write(0, 4); // scfsi
    for _gr in 0..2 {
        w.write(part2_3_length, 12);
        w.write(0, 9); // big_values: none, everything is in the count1 partition
        w.write(GLOBAL_GAIN, 8);
        w.write(0, 4); // scalefac_compress: slen1 = slen2 = 0, so part2 is 0 bits long
        match cfg.block {
            Block::Short { mixed } => {
                w.write(1, 1); // window_switching_flag
                w.write(0b10, 2); // block_type: short
                w.write(u32::from(mixed), 1); // mixed_block_flag
                w.write(0, 5); // table_select[0]
                w.write(0, 5); // table_select[1]
                w.write(0, 3); // subblock_gain[0]
                w.write(0, 3); // subblock_gain[1]
                w.write(0, 3); // subblock_gain[2]
            }
            Block::Long => {
                w.write(0, 1); // window_switching_flag
                w.write(0, 5); // table_select[0]
                w.write(0, 5); // table_select[1]
                w.write(0, 5); // table_select[2]
                w.write(0, 4); // region0_count
                w.write(0, 3); // region1_count
            }
        }
        w.write(0, 1); // preflag
        w.write(0, 1); // scalefac_scale
        w.write(1, 1); // count1table_select: quads table B (fixed 4-bit codes)
    }

    // ---- main_data ----
    // part3: count1 quadruples. In quads table B the code for value V is the 4-bit code 15 - V,
    // followed by one sign bit per non-zero coefficient (0 == positive).
    for _gr in 0..2 {
        for &v in &quads {
            w.write(15 - v, 4);
            w.write(0, v.count_ones());
        }
    }

    let mut frame = w.finish();
    assert!(frame.len() <= cfg.frame_size(), "frame overflow: {} bytes", frame.len());
    frame.resize(cfg.frame_size(), 0);
    frame
}

fn build_stream(n_frames: usize, cfg: Cfg) -> Vec<u8> {
    let frame = build_frame(cfg);
    let mut out = Vec::with_capacity(n_frames * frame.len());
    for _ in 0..n_frames {
        out.extend_from_slice(&frame);
    }
    out
}

/// Decode an MP3 byte stream through Symphonia's real public probe/demux/decode path.
fn decode(bytes: &[u8]) -> Result<Vec<f32>> {
    let mss = MediaSourceStream::new(Box::new(Cursor::new(bytes.to_vec())), Default::default());

    let mut hint = Hint::new();
    hint.with_extension("mp3");

    let mut format =
        symphonia::default::get_probe().probe(&hint, mss, FormatOptions::default(), Default::default())?;

    let track = format.default_track(TrackType::Audio).expect("audio track");
    let track_id = track.id;
    let params = match &track.codec_params {
        Some(CodecParameters::Audio(p)) => p.clone(),
        _ => panic!("no audio codec params"),
    };

    let dec_opts = AudioDecoderOptions::default().gapless(false);
    let mut decoder = symphonia::default::get_codecs().make_audio_decoder(&params, &dec_opts)?;

    let mut samples: Vec<f32> = Vec::new();
    let mut scratch: Vec<f32> = Vec::new();

    while let Some(packet) = format.next_packet()? {
        if packet.track_id != track_id {
            continue;
        }
        decoder.decode(&packet)?;
        let buf: GenericAudioBufferRef<'_> = decoder.last_decoded();
        buf.copy_to_vec_interleaved(&mut scratch);
        samples.extend_from_slice(&scratch);
    }

    Ok(samples)
}

/// Decode an .mp3 file with ffmpeg (an independent reference decoder), if it is installed.
fn ffmpeg_decode(path: &Path) -> Option<Vec<f32>> {
    let out = std::process::Command::new("ffmpeg")
        .args(["-v", "error", "-i"])
        .arg(path)
        .args(["-f", "f32le", "-acodec", "pcm_f32le", "-"])
        .output()
        .ok()?;

    if !out.status.success() {
        eprintln!("ffmpeg failed: {}", String::from_utf8_lossy(&out.stderr));
        return None;
    }

    Some(out.stdout.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect())
}

fn rms(s: &[f32]) -> f64 {
    if s.is_empty() {
        return 0.0;
    }
    (s.iter().map(|&v| f64::from(v) * f64::from(v)).sum::<f64>() / s.len() as f64).sqrt()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert!(!a.is_empty() && a.len() == b.len(), "length mismatch: {} vs {}", a.len(), b.len());
    a.iter().zip(b).map(|(&x, &y)| (x - y).abs()).fold(0.0f32, f32::max)
}

/// The tolerance symphonia-check uses for a fully compliant decoder (~2^-17, -102.4 dB).
const ABS_MAX_ALLOWABLE_SAMPLE_DELTA: f32 = 0.00001;

const N_FRAMES: usize = 8;

fn out_dir() -> PathBuf {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("out");
    std::fs::create_dir_all(&dir).expect("create out dir");
    dir
}

fn write_mp3(name: &str, bytes: &[u8]) -> PathBuf {
    let path = out_dir().join(name);
    std::fs::write(&path, bytes).expect("write mp3");
    path
}

fn main() {
    let cfg_a = Cfg { sr_idx: 0, block: Block::Short { mixed: true }, n_quads: 144 };
    let cfg_b = Cfg { sr_idx: 0, block: Block::Short { mixed: true }, n_quads: 9 };
    let cfg_c = Cfg { sr_idx: 0, block: Block::Short { mixed: false }, n_quads: 144 };

    let cases = [
        ("A", "mixed_full.mp3", "mixed_block_flag=1, coefficients 0..576", cfg_a),
        ("B", "mixed_lowonly.mp3", "mixed_block_flag=1, coefficients 0..36 ", cfg_b),
        ("C", "short_full.mp3", "mixed_block_flag=0, coefficients 0..576", cfg_c),
    ];

    let mut paths = Vec::new();
    let mut pcm = Vec::new();
    for (_, name, _, cfg) in &cases {
        let stream = build_stream(N_FRAMES, *cfg);
        paths.push(write_mp3(name, &stream));
        pcm.push(decode(&stream).expect("symphonia decode"));
    }
    println!("wrote {}/{{mixed_full,mixed_lowonly,short_full}}.mp3", out_dir().display());
    println!();

    println!("symphonia, 44100 Hz mono, 8 frames:");
    for ((tag, _, desc, _), p) in cases.iter().zip(&pcm) {
        println!("  {tag}  {desc} : {} samples, rms {:.9}", p.len(), rms(p));
    }
    println!();

    let d_ab = max_abs_diff(&pcm[0], &pcm[1]);
    let d_ac = max_abs_diff(&pcm[0], &pcm[2]);
    println!("  max |A - B| = {d_ab:.9}   (A and B carry different spectral data: MUST be > 0)");
    println!("  max |A - C| = {d_ac:.9}   (sanity: a mixed and a short block do differ)");
    println!();

    // ---- Cross-check against ffmpeg, if available ----
    let refs: Vec<Option<Vec<f32>>> = paths.iter().map(|p| ffmpeg_decode(p)).collect();
    let have_ffmpeg = refs.iter().all(Option::is_some);

    if have_ffmpeg {
        println!("ffmpeg (reference decoder), same three files:");
        for ((tag, _, desc, _), r) in cases.iter().zip(&refs) {
            let r = r.as_ref().expect("checked");
            println!("  {tag}  {desc} : {} samples, rms {:.9}", r.len(), rms(r));
        }
        println!();
        for (((tag, _, _, _), r), p) in cases.iter().zip(&refs).zip(&pcm) {
            let r = r.as_ref().expect("checked");
            println!("  max |symphonia({tag}) - ffmpeg({tag})| = {:.9}", max_abs_diff(p, r));
        }
        println!();

        // Sweep: sample rate x block type x rzero position, all against ffmpeg.
        println!("sweep vs ffmpeg (tolerance {ABS_MAX_ALLOWABLE_SAMPLE_DELTA}, symphonia-check's own):");
        println!("  {:<8} {:<14} {:>7}  {:>13}  {}", "rate", "block", "coefs", "max delta", "");
        let mut n_fail = 0;
        let mut n_total = 0;
        for sr_idx in 0..3 {
            for block in [Block::Long, Block::Short { mixed: false }, Block::Short { mixed: true }] {
                for n_quads in [9, 20, 45, 144] {
                    let cfg = Cfg { sr_idx, block, n_quads };
                    let stream = build_stream(N_FRAMES, cfg);
                    let path = write_mp3("sweep.mp3", &stream);
                    let tgt = decode(&stream).expect("symphonia decode");
                    let Some(reference) = ffmpeg_decode(&path) else { continue };

                    let delta = max_abs_diff(&tgt, &reference);
                    let ok = delta <= ABS_MAX_ALLOWABLE_SAMPLE_DELTA;
                    n_total += 1;
                    n_fail += usize::from(!ok);

                    println!(
                        "  {:<8} {:<14} {:>7}  {:>13.9}  {}",
                        cfg.sample_rate(),
                        match block {
                            Block::Long => "long",
                            Block::Short { mixed: false } => "short",
                            Block::Short { mixed: true } => "short mixed",
                        },
                        n_quads * 4,
                        delta,
                        if ok { "ok" } else { "MISMATCH" },
                    );
                }
            }
        }
        println!();
        println!("  {n_fail} of {n_total} sweep cases exceed the tolerance");
        println!();
    }
    else {
        println!("ffmpeg not on PATH - skipping the reference-decoder cross-check and the sweep.");
        println!();
    }

    if d_ab == 0.0 {
        println!("BUG REPRODUCED: zeroing every spectral coefficient above index 36 changed");
        println!("  nothing at all. Mixed blocks are decoded as if only sub-bands 0..2 existed");
        println!("  (0 - 1378 Hz at 44100 Hz); sub-bands 2..32 are overwritten with zeros.");
        std::process::exit(1);
    }

    println!("OK: spectral coefficients above sub-band 2 do affect the decoded output.");
}
